ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  "message": {
    "subject": "MULESOFT: SALESFORCE_CREATION_ERROR",
    "body": {
      "contentType": "Text",
      "content": write(payload, "application/json")
    },
    "toRecipients": (p('secure::errorEmailTo') splitBy  (",")) map (item,index) -> {
        "emailAddress": {
            "address": item
        }
    }
  },
  "saveToSentItems": "false"
}

